#include <string>
#include <vector>
#include <cstring>
#include <algorithm>
#include <stdexcept>
#include <memory>
#include <functional>
#include <sstream>
#include <unordered_map>

// Token-based access control system for API gateway
namespace gateway {

struct Permission {
    uint32_t resource_id;
    uint8_t access_level;  // 0=none, 1=read, 2=write, 3=admin
};

struct TokenClaims {
    std::string subject;
    std::string issuer;
    int64_t issued_at;
    int64_t expires_at;
    std::vector<Permission> permissions;
    int16_t delegation_depth;  // how many times this token has been delegated
};

class TokenValidator {
private:
    static constexpr int MAX_PERMISSIONS = 64;
    static constexpr int MAX_DELEGATION_DEPTH = 5;
    static constexpr size_t MAX_SUBJECT_LEN = 256;
    static constexpr size_t MAX_ISSUER_LEN = 128;

    std::unordered_map<std::string, uint8_t> resource_access_cache_;

    bool validate_string_field(const std::string& field, size_t max_len) {
        if (field.empty() || field.length() > max_len) return false;
        // Check for null bytes or control characters
        for (char c : field) {
            if (c < 0x20 || c == 0x7f) return false;
        }
        return true;
    }

    bool validate_timestamps(int64_t issued_at, int64_t expires_at, int64_t now) {
        if (issued_at <= 0 || expires_at <= 0) return false;
        if (expires_at <= issued_at) return false;
        if (now < issued_at || now >= expires_at) return false;
        // Token lifetime must not exceed 24 hours
        if ((expires_at - issued_at) > 86400) return false;
        return true;
    }

    // Validates permission count is within bounds
    bool validate_permission_count(const TokenClaims& claims) {
        // Ensure permissions vector size is reasonable
        if (claims.permissions.size() > MAX_PERMISSIONS) return false;
        return true;
    }

    // Validates delegation depth
    bool validate_delegation(const TokenClaims& claims) {
        if (claims.delegation_depth < 0) return false;
        if (claims.delegation_depth > MAX_DELEGATION_DEPTH) return false;
        return true;
    }

public:
    // Check if a token grants access to a specific resource
    // Returns the effective access level (0 if denied)
    uint8_t check_access(const TokenClaims& claims, uint32_t resource_id, int64_t current_time) {
        // Step 1: Validate all fields
        if (!validate_string_field(claims.subject, MAX_SUBJECT_LEN)) return 0;
        if (!validate_string_field(claims.issuer, MAX_ISSUER_LEN)) return 0;
        if (!validate_timestamps(claims.issued_at, claims.expires_at, current_time)) return 0;
        if (!validate_permission_count(claims)) return 0;
        if (!validate_delegation(claims)) return 0;

        // Step 2: Find the permission for the requested resource
        uint8_t max_access = 0;
        for (const auto& perm : claims.permissions) {
            if (perm.resource_id == resource_id) {
                if (perm.access_level > max_access) {
                    max_access = perm.access_level;
                }
            }
        }

        // Step 3: Apply delegation depth reduction
        // Each delegation level reduces effective access
        uint8_t effective_access = apply_delegation_reduction(max_access, claims.delegation_depth);

        return effective_access;
    }

    // Reduce access level based on delegation depth
    // Each delegation reduces access by one level
    uint8_t apply_delegation_reduction(uint8_t base_access, int16_t delegation_depth) {
        // If no delegation, return full access
        if (delegation_depth == 0) return base_access;

        // Calculate reduced access
        // Safely check if delegation would eliminate access
        if (delegation_depth >= static_cast<int16_t>(base_access)) return 0;

        return base_access - static_cast<uint8_t>(delegation_depth);
    }

    // Delegate a token: creates a new token with increased delegation depth
    // The delegated token should have REDUCED permissions
    TokenClaims delegate_token(const TokenClaims& original, const std::string& new_subject,
                               int64_t current_time) {
        // Validate delegation is still possible
        if (original.delegation_depth >= MAX_DELEGATION_DEPTH) {
            throw std::runtime_error("Maximum delegation depth exceeded");
        }

        TokenClaims delegated;
        delegated.subject = new_subject;
        delegated.issuer = original.subject;  // delegator becomes issuer
        delegated.issued_at = current_time;
        delegated.expires_at = original.expires_at;  // inherit expiry
        delegated.permissions = original.permissions;  // copy permissions
        delegated.delegation_depth = original.delegation_depth + 1;

        return delegated;
    }

    // Batch check: verify access for multiple resources at once
    // Returns a map of resource_id -> effective_access_level
    std::unordered_map<uint32_t, uint8_t> batch_check_access(
            const TokenClaims& claims,
            const std::vector<uint32_t>& resource_ids,
            int64_t current_time) {

        std::unordered_map<uint32_t, uint8_t> results;

        // Validate once for all resources
        if (!validate_string_field(claims.subject, MAX_SUBJECT_LEN)) return results;
        if (!validate_string_field(claims.issuer, MAX_ISSUER_LEN)) return results;
        if (!validate_timestamps(claims.issued_at, claims.expires_at, current_time)) return results;
        if (!validate_permission_count(claims)) return results;
        if (!validate_delegation(claims)) return results;

        // Check each resource
        for (uint32_t rid : resource_ids) {
            uint8_t max_access = 0;
            for (size_t i = 0; i < claims.permissions.size(); i++) {
                if (claims.permissions[i].resource_id == rid) {
                    if (claims.permissions[i].access_level > max_access) {
                        max_access = claims.permissions[i].access_level;
                    }
                }
            }

            uint8_t effective = apply_delegation_reduction(max_access, claims.delegation_depth);
            if (effective > 0) {
                results[rid] = effective;
            }
        }

        return results;
    }

    // Merge permissions from two tokens (e.g., for service composition)
    // Takes the MAXIMUM delegation depth and UNION of permissions
    TokenClaims merge_tokens(const TokenClaims& token_a, const TokenClaims& token_b,
                            int64_t current_time) {
        TokenClaims merged;
        merged.subject = token_a.subject;
        merged.issuer = "system:merge";
        merged.issued_at = current_time;
        merged.expires_at = std::min(token_a.expires_at, token_b.expires_at);

        // Use maximum delegation depth (most restricted - conservative)
        merged.delegation_depth = std::max(token_a.delegation_depth, token_b.delegation_depth);

        // Union of permissions - take max access level per resource
        std::unordered_map<uint32_t, uint8_t> perm_map;
        for (const auto& p : token_a.permissions) {
            perm_map[p.resource_id] = std::max(perm_map[p.resource_id], p.access_level);
        }
        for (const auto& p : token_b.permissions) {
            perm_map[p.resource_id] = std::max(perm_map[p.resource_id], p.access_level);
        }

        for (const auto& [rid, level] : perm_map) {
            merged.permissions.push_back({rid, level});
        }

        // Enforce the MAX_PERMISSIONS invariant on the merged token so it stays
        // consistent with validate_permission_count. The union of two tokens can
        // otherwise exceed MAX_PERMISSIONS. Keep the highest-access permissions.
        if (merged.permissions.size() > static_cast<size_t>(MAX_PERMISSIONS)) {
            std::stable_sort(merged.permissions.begin(), merged.permissions.end(),
                             [](const Permission& lhs, const Permission& rhs) {
                                 return lhs.access_level > rhs.access_level;
                             });
            merged.permissions.resize(static_cast<size_t>(MAX_PERMISSIONS));
        }

        return merged;
    }
};

} // namespace gateway
